def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    DIGITS = set("0123456789")

    def parse_amount(s):
        if not s or any(c not in DIGITS for c in s):
            return None
        return int(s)

    bal = {}
    frozen = set()
    history = []
    rejected = []

    for i, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0]
        ok = False
        if verb == "open" and len(t) == 3:
            a = t[1]
            n = parse_amount(t[2])
            if n is not None and a not in bal:
                bal[a] = n
                history.append(("open", a))
                ok = True
        elif verb == "deposit" and len(t) == 3:
            a = t[1]
            n = parse_amount(t[2])
            if n is not None and n > 0 and a in bal:
                bal[a] += n
                history.append(("deposit", a, n))
                ok = True
        elif verb == "withdraw" and len(t) == 3:
            a = t[1]
            n = parse_amount(t[2])
            if (n is not None and n > 0 and a in bal
                    and a not in frozen and bal[a] >= n):
                bal[a] -= n
                history.append(("withdraw", a, n))
                ok = True
        elif verb == "transfer" and len(t) == 4:
            a, b = t[1], t[2]
            n = parse_amount(t[3])
            if (n is not None and n > 0 and a != b and a in bal and b in bal
                    and a not in frozen and bal[a] >= n):
                bal[a] -= n
                bal[b] += n
                history.append(("transfer", a, b, n))
                ok = True
        elif verb == "freeze" and len(t) == 2:
            a = t[1]
            if a in bal and a not in frozen:
                frozen.add(a)
                history.append(("freeze", a))
                ok = True
        elif verb == "unfreeze" and len(t) == 2:
            a = t[1]
            if a in bal and a in frozen:
                frozen.discard(a)
                history.append(("unfreeze", a))
                ok = True
        elif verb == "undo" and len(t) == 1:
            if history:
                h = history.pop()
                k = h[0]
                if k == "open":
                    del bal[h[1]]
                    frozen.discard(h[1])
                elif k == "deposit":
                    bal[h[1]] -= h[2]
                elif k == "withdraw":
                    bal[h[1]] += h[2]
                elif k == "transfer":
                    bal[h[1]] += h[3]
                    bal[h[2]] -= h[3]
                elif k == "freeze":
                    frozen.discard(h[1])
                elif k == "unfreeze":
                    frozen.add(h[1])
                ok = True
        if not ok:
            rejected.append(i)

    return dict(bal), rejected
